    const newsletterStatus = document.getElementById('newsletter-status');

    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = newsletterForm.querySelector('input').value;

            // Simulate API call
            newsletterStatus.textContent = 'Subscribing...';

            setTimeout(() => {
                newsletterStatus.textContent = `Thank you for subscribing with ${email}!`;
                newsletterForm.reset();

                setTimeout(() => {
                    newsletterStatus.textContent = '';
                }, 5000);
            }, 1000);
        });
    }

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();
            const targetId = this.getAttribute('href');
            if (targetId === '#') return;

            const targetElement = document.querySelector(targetId);
            if (targetElement) {
                targetElement.scrollIntoView({
                    behavior: 'smooth'
                });
            }
        });
    });

    // Simple fade-in effect on scroll
    const observerOptions = {
        threshold: 0.1
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('fade-in');
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Apply fade-in class to sections (need to add CSS for this if desired)
    // document.querySelectorAll('section').forEach(section => {
    //     observer.observe(section);
    // });
});
