", direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_minimal/shopping-home-page--framework-vanilla-js--style-modern/google/gemini-3-flash-preview__s3/script.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='document.addEventListener('DOMContentLoaded', () => {
    // Cart functionality
    let cartCount = 0;
    const cartCountElement = document.querySelector('.cart-count');
    const addToCartButtons = document.querySelectorAll('.add-to-cart');

    addToCartButtons.forEach(button => {
        button.addEventListener('click', () => {
            const productName = button.getAttribute('data-product');
            cartCount++;
            updateCart();

            // Visual feedback
            const originalText = button.textContent;
            button.textContent = 'Added!';
            button.classList.add('btn-primary');
            button.classList.remove('btn-secondary');

            setTimeout(() => {
                button.textContent = originalText;
                button.classList.remove('btn-primary');
                button.classList.add('btn-secondary');
            }, 1500);

            console.log(`Added ${productName} to cart.`);
        });
    });

    function updateCart() {
        cartCountElement.textContent = cartCount;
        const cartBtn = document.querySelector('.cart-btn');
        cartBtn.setAttribute('aria-label', `Cart, ${cartCount} items`);
    }

    // Newsletter functionality
    const newsletterForm = document.getElementById('newsletter-form');
    const newsletterStatus = document.getElementById('newsletter-status');

    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = newsletterForm.querySelector('input').value;

            // Simulate API call
            newsletterStatus.textContent = 'Subscribing...';

            setTimeout(() => {
                newsletterStatus.textContent = `Thank you for subscribing with ${email}!`;
                newsletterForm.reset();

                setTimeout(() => {
                    newsletterStatus.textContent = '';
                }, 5000);
            }, 1000);
        });
    }

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();
            const targetId = this.getAttribute('href');
            if (targetId === '#') return;

            const targetElement = document.querySelector(targetId);
            if (targetElement) {
                targetElement.scrollIntoView({
                    behavior: 'smooth'
                });
            }
        });
    });

    // Simple fade-in effect on scroll
    const observerOptions = {
        threshold: 0.1
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('fade-in');
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Apply fade-in class to sections
    document.querySelectorAll('section').forEach(section => {
        section.style.opacity = '0'; // Initial state for intersection observer
        observer.observe(section);
    });
});
