', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_minimal/shopping-home-page--framework-vanilla-js--style-modern/google/gemini-3-flash-preview__s3/styles.css', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents=':root {
    --primary-color: #1a1a1a;
    --secondary-color: #f4f4f4;
    --accent-color: #3d5a80;
    --text-color: #333333;
    --light-text: #666666;
    --white: #ffffff;
    --max-width: 1200px;
    --transition: all 0.3s ease;
    --shadow: 0 4px 6px rgba(0,0,0,0.05);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--text-color);
    line-height: 1.6;
    background-color: var(--white);
    overflow-x: hidden;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

img {
    max-width: 100%;
    display: block;
}

.container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 2rem;
}

.btn {
    display: inline-block;
    padding: 0.8rem 1.5rem;
    border-radius: 4px;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: var(--transition);
    text-align: center;
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--white);
}

.btn-primary:hover {
    background-color: #333;
    transform: translateY(-2px);
}

.btn-secondary {
    background-color: transparent;
    border: 1px solid var(--primary-color);
    color: var(--primary-color);
}

.btn-secondary:hover {
    background-color: var(--primary-color);
    color: var(--white);
}

.btn-white {
    background-color: var(--white);
    color: var(--primary-color);
}

.btn-white:hover {
    background-color: #eee;
}

/* Header */
.main-header {
    background-color: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    position: sticky;
    top: 0;
    z-index: 100;
    border-bottom: 1px solid #eee;
    padding: 1rem 0;
}

.nav-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a:hover {
    color: var(--light-text);
}

.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.icon-btn {
    background: none;
    border: none;
    cursor: pointer;
    position: relative;
    padding: 0.5rem;
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background-color: var(--primary-color);
    color: var(--white);
    font-size: 0.7rem;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero */
.hero {
    height: 80vh;
    background-image: linear-gradient(rgba(0,0,0,0.3), rgba(0,0,0,0.3)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?auto=format&fit=crop&q=80&w=2000');
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
    color: var(--white);
    margin-bottom: 4rem;
}

.hero-content h1 {
    font-size: clamp(2.5rem, 5vw, 4rem);
    margin-bottom: 1rem;
    font-weight: 700;
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: 2rem;
    max-width: 600px;
}

/* Featured Products */
.featured-products {
    margin-bottom: 6rem;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 2.5rem;
}

.section-header h2 {
    font-size: 2rem;
}

.link-more {
    color: var(--light-text);
    border-bottom: 1px solid transparent;
}

.link-more:hover {
    border-bottom-color: var(--light-text);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    transition: var(--transition);
}

.product-image {
    background-color: #f9f9f9;
    aspect-ratio: 4/5;
    overflow: hidden;
    margin-bottom: 1rem;
    border-radius: 4px;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
    font-weight: 500;
}

.price {
    font-weight: 600;
    margin-bottom: 1rem;
}

.add-to-cart {
    width: 100%;
}

/* Deals */
.deals-section {
    background-color: var(--secondary-color);
    padding: 6rem 0;
    margin-bottom: 6rem;
}

.deals-banner {
    background-image: linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url('https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&q=80&w=2000');
    background-size: cover;
    background-position: center;
    padding: 6rem;
    border-radius: 8px;
    color: var(--white);
    text-align: center;
}

.badge {
    display: inline-block;
    background-color: var(--accent-color);
    padding: 0.3rem 0.8rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    margin-bottom: 1.5rem;
    text-transform: uppercase;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.deals-content p {
    font-size: 1.1rem;
    margin-bottom: 2rem;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

/* Editorial */
.editorial {
    margin-bottom: 8rem;
}

.editorial-grid {
    display: grid;
    grid-template-columns: 1.2fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial-image img {
    border-radius: 4px;
    box-shadow: var(--shadow);
}

.editorial-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.editorial-content p {
    margin-bottom: 1.5rem;
    color: var(--light-text);
}

.link-underline {
    font-weight: 600;
    border-bottom: 2px solid var(--primary-color);
    padding-bottom: 2px;
}

/* Newsletter */
.newsletter {
    margin-bottom: 8rem;
}

.newsletter-card {
    background-color: var(--primary-color);
    color: var(--white);
    padding: 4rem;
    text-align: center;
    border-radius: 8px;
}

.newsletter-card h2 {
    font-size: 2rem;
    margin-bottom: 1rem;
}

.newsletter-card p {
    margin-bottom: 2rem;
    opacity: 0.8;
}

.newsletter-form {
    display: flex;
    gap: 1rem;
    max-width: 500px;
    margin: 0 auto;
}

.newsletter-form input {
    flex: 1;
    padding: 0.8rem 1rem;
    border: none;
    border-radius: 4px;
}

.status-msg {
    margin-top: 1rem;
    font-size: 0.9rem;
}

/* Footer */
.main-footer {
    background-color: #f9f9f9;
    padding: 4rem 0 2rem;
    border-top: 1px solid #eee;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr repeat(3, 1fr);
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    display: block;
    margin-bottom: 1rem;
}

.footer-brand p {
    color: var(--light-text);
}

.footer-links h3 {
    font-size: 1rem;
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.footer-links li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--light-text);
}

.footer-links a:hover {
    color: var(--primary-color);
}

.footer-bottom {
    border-top: 1px solid #eee;
    padding-top: 2rem;
    text-align: center;
    color: var(--light-text);
    font-size: 0.9rem;
}

/* Animations */
.fade-in {
    animation: fadeIn 0.8s ease forwards;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Responsive */
@media (max-width: 992px) {
    .editorial-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
    .editorial-image {
        order: 2;
    }
    .footer-grid {
        grid-template-columns: 1fr 1fr;
        gap: 2rem;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .hero {
        height: 60vh;
    }
    .deals-banner {
        padding: 3rem 1.5rem;
    }
    .newsletter-form {
        flex-direction: column;
    }
}
